const files = {"/assets/adoption-tall.png": ["image/png", ""], "/assets/adoption.png": ["image/png", ""], "/assets/capital-tall.png": ["image/png", ""], "/assets/capital.png": ["image/png", ""], "/assets/futures-tall.png": ["image/png", ""], "/assets/futures.png": ["image/png", ""], "/assets/infra-tall.png": ["image/png", ""], "/assets/infra.png": ["image/png", ""], "/assets/kickoff.png": ["image/png", ""], "/assets/logo.png": ["image/png", ""], "/assets/site-logo.png": ["image/png", ""], "/assets/social-linkedin.png": ["image/png", ""], "/assets/social-web.png": ["image/png", ""], "/assets/social-x.png": ["image/png", ""], "/assets/stablecoin-tall.png": ["image/png", ""], "/assets/stablecoin.png": ["image/png", ""], "/assets/token-tall.png": ["image/png", ""], "/assets/token.png": ["image/png", ""], "/assets/trade-tall.png": ["image/png", ""], "/assets/trade.png": ["image/png", ""], "/assets/tradfi-tall.png": ["image/png", ""], "/assets/tradfi.png": ["image/png", ""], "/assets/womens-day.png": ["image/png", ""], "/calendar/collective-capital/index.html": ["text/html; charset=utf-8", ""], "/calendar/decentralized-futures/index.html": ["text/html; charset=utf-8", ""], "/calendar/si-her-trade/index.html": ["text/html; charset=utf-8", ""], "/calendar/stablecoin-confidence/index.html": ["text/html; charset=utf-8", ""], "/calendar/token-fundamentals/index.html": ["text/html; charset=utf-8", ""], "/calendar/tradfi-to-defi/index.html": ["text/html; charset=utf-8", ""], "/calendar/what-the-infra/index.html": ["text/html; charset=utf-8", ""], "/index.html": ["text/html; charset=utf-8", ""], "/newsletter/index.html": ["text/html; charset=utf-8", ""]};
export default { async fetch(request) {
  if (!['GET','HEAD'].includes(request.method)) return new Response('Method not allowed',{status:405});
  const path = new URL(request.url).pathname;
  let key = path.endsWith('/') ? path + 'index.html' : path;
  if (!files[key] && files[key + '/index.html']) return Response.redirect(new URL(path + '/', request.url), 308);
  const entry = files[key];
  if (!entry) return new Response('Not found', {status:404});
  const headers = {'Content-Type':entry[0], 'X-Content-Type-Options':'nosniff'};
  if (key.endsWith('.ics')) {headers['Content-Disposition']='attachment; filename="'+key.split('/').pop()+'"'; headers['Cache-Control']='no-store';}
  const bytes = Uint8Array.from(atob(entry[1]), c => c.charCodeAt(0));
  return new Response(request.method === 'HEAD' ? null : bytes, {headers});
}};
